```
bool aktif[3] = {false, true, true};   // KAC, CIZGI, DOLAS
int secilen = 2;

void setup() {
  Serial.begin(9600);
  for (int i = 0; i < 3; i++) {
    if (aktif[i]) { secilen = i; break; }
  }
  Serial.println(secilen);
}

void loop() {}
```

